#include <stdlib.h>

int main() {
    // Ejemplo de fuga de memoria
    int *leak = (int*)malloc(sizeof(int) * 10);
    // Se olvidó liberar la memoria asignada
    return 0;
}

invalidAccess.example:
#include <stdlib.h>

int main() {
    // Ejemplo de lectura/escritura inválida
    int *arr = (int*)malloc(sizeof(int) * 5);
    arr[5] = 10;  // Acceso fuera de límites
    free(arr);
    return 0;
}

