doubleFree.example:
#include <stdlib.h>

int main() {
    int *ptr = (int*)malloc(sizeof(int));
    free(ptr);
    free(ptr);  // Doble liberación
    return 0;
}

mismatchedFree.example:
#include <stdlib.h>

int main() {
    int *arr = (int*)malloc(10 * sizeof(int));
    delete[] arr;  // Función de liberación incorrecta
    return 0;
}

